/// Returns `NULL` on invalid parameters; release the handle with `wickra_ppo_free`.
#[no_mangle]
pub extern "C" fn wickra_ppo_new(fast: usize, slow: usize) -> *mut Ppo {
    match Ppo::new(fast, slow) {
        Ok(ind) => Box::into_raw(Box::new(ind)),
        Err(_) => ptr::null_mut(),
    }
}

/// Feed one value; returns the output, or `NaN` during warmup / on a `NULL` handle.
///
/// # Safety
/// `handle` must be a valid pointer from `wickra_ppo_new` (not yet freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_ppo_update(handle: *mut Ppo, value: f64) -> f64 {
    match handle.as_mut() {
        Some(ind) => ind.update(value).unwrap_or(f64::NAN),
        None => f64::NAN,
    }
}

/// Run over `input[0..n]`, writing one output per input into `out[0..n]` (`NaN` at warmup).
///
/// # Safety
/// `handle` must be valid (from `wickra_ppo_new`, not freed). `input` and `out` must
/// each point to at least `n` readable / writable `double`s.
#[no_mangle]
pub unsafe extern "C" fn wickra_ppo_batch(
    handle: *mut Ppo,
    input: *const f64,
    out: *mut f64,
    n: usize,
) {
    if handle.is_null() || input.is_null() || out.is_null() {
        return;
    }
    let ind = &mut *handle;
    let inputs = slice::from_raw_parts(input, n);
    let outputs = slice::from_raw_parts_mut(out, n);
    for (slot, &value) in outputs.iter_mut().zip(inputs) {
        *slot = ind.update(value).unwrap_or(f64::NAN);
    }
}

/// Reset all internal state. No-op if `handle` is `NULL`.
///
/// # Safety
/// `handle` must be valid (from `wickra_ppo_new`, not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_ppo_reset(handle: *mut Ppo) {
    if let Some(ind) = handle.as_mut() {
        ind.reset();
    }
}

/// Destroy a handle created by `wickra_ppo_new`. No-op if `handle` is `NULL`.
///
/// # Safety
/// `handle` must have been returned by `wickra_ppo_new` and not previously freed, or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_ppo_free(handle: *mut Ppo) {
    if !handle.is_null() {
        drop(Box::from_raw(handle));
    }
}

