// ===== Candlestick patterns (OHLC -> signal) =====

/// Create a `Hammer` candlestick-pattern detector (parameter-free).
///
/// Release the handle with `wickra_hammer_free`.
#[no_mangle]
pub extern "C" fn wickra_hammer_new() -> *mut Hammer {
    Box::into_raw(Box::new(Hammer::new()))
}

/// Feed one OHLC candle; returns the pattern signal, or `NaN` during warmup / on a
/// `NULL` handle / if the candle is invalid (e.g. `high < low`).
///
/// # Safety
/// `handle` must be a valid pointer from `wickra_hammer_new` (not yet freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_hammer_update(
    handle: *mut Hammer,
    open: f64,
    high: f64,
    low: f64,
    close: f64,
) -> f64 {
    let Some(ind) = handle.as_mut() else {
        return f64::NAN;
    };
    match Candle::new(open, high, low, close, 0.0, 0) {
        Ok(candle) => ind.update(candle).unwrap_or(f64::NAN),
        Err(_) => f64::NAN,
    }
}

/// Run over the OHLC series `open/high/low/close[0..n]`, writing one signal per candle
/// into `out[0..n]` (`NaN` at warmup or on an invalid candle).
///
/// # Safety
/// `handle` must be valid (from `wickra_hammer_new`, not freed). `open`, `high`, `low`,
/// `close` and `out` must each point to at least `n` `double`s.
#[no_mangle]
pub unsafe extern "C" fn wickra_hammer_batch(
    handle: *mut Hammer,
    open: *const f64,
    high: *const f64,
    low: *const f64,
    close: *const f64,
    out: *mut f64,
    n: usize,
) {
    if handle.is_null()
        || open.is_null()
        || high.is_null()
        || low.is_null()
        || close.is_null()
        || out.is_null()
    {
        return;
    }
    let ind = &mut *handle;
    let opens = slice::from_raw_parts(open, n);
    let highs = slice::from_raw_parts(high, n);
    let lows = slice::from_raw_parts(low, n);
    let closes = slice::from_raw_parts(close, n);
    let outputs = slice::from_raw_parts_mut(out, n);
    for (idx, slot) in outputs.iter_mut().enumerate() {
        *slot = match Candle::new(opens[idx], highs[idx], lows[idx], closes[idx], 0.0, 0) {
            Ok(candle) => ind.update(candle).unwrap_or(f64::NAN),
            Err(_) => f64::NAN,
        };
    }
}

/// Reset all internal state. No-op if `handle` is `NULL`.
///
/// # Safety
/// `handle` must be valid (from `wickra_hammer_new`, not freed), or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_hammer_reset(handle: *mut Hammer) {
    if let Some(ind) = handle.as_mut() {
        ind.reset();
    }
}

/// Destroy a handle created by `wickra_hammer_new`. No-op if `handle` is `NULL`.
///
/// # Safety
/// `handle` must have been returned by `wickra_hammer_new` and not previously freed, or `NULL`.
#[no_mangle]
pub unsafe extern "C" fn wickra_hammer_free(handle: *mut Hammer) {
    if !handle.is_null() {
        drop(Box::from_raw(handle));
    }
}

